import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.C9sp7nFj.js";const _=JSON.parse('{"title":"MovLSync 传送带直线同步运动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/14. 传送带跟随指令/MovLSync.md","filePath":"3. 指令/14. 传送带跟随指令/MovLSync.md","lastUpdated":1778862643000}'),r={name:"3. 指令/14. 传送带跟随指令/MovLSync.md"};function n(l,t,c,i,S,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="movlsync-传送带直线同步运动" tabindex="-1">MovLSync 传送带直线同步运动 <a class="header-anchor" href="#movlsync-传送带直线同步运动" aria-label="Permalink to &quot;MovLSync 传送带直线同步运动&quot;">​</a></h1><p>该指令为传送带同步运动指令，通过该指令可以使机器人 TCP 点以设定的速度直线运动到目标位置，并保持与传送带的同步运动。与 MovJ 相同，在执行完该指令时可以附加进行 IO 操作。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovLSync(P, [V], [Tool], Coord, [PayLoad], [SyncGoto], Height, ConvyGoto, [DO])</p><p>MovLSync(目标点, [速度], [工具], 坐标系, [负载], [同步丢弃跳转标签], 抬升高度, 同步后丢弃跳转标签, [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>CPOS 变量</td><td>跟随目标点，其数值是相对于目标物体识别点的偏移量，非示教所得</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定机器人末端的平移速度、旋转速度以及外部轴的移动速度。SPEED 变量中的 tcp、ori 分量有效，有外部轴时 exj_l、exj_r 分量有效</td><td>可选，默认 V4000</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数</td><td>可选，默认当前系统工具参数</td></tr><tr><td>Coord</td><td>SYNCOORD 变量</td><td>机器人执行该轨迹时使用的动坐标系，需与传送带配置界面中启用的动坐标系一致</td><td>必填</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数</td><td>可选，默认当前系统负载参数</td></tr><tr><td>[SyncGoto]</td><td>label</td><td>同步过程中无法实现同步时的跳转标签。执行失败时程序指针转至该标签执行丢弃操作</td><td>可选，默认跳转到 &quot; 同步后放弃时跳转标签 &quot; 所用的 Label</td></tr><tr><td>Height</td><td>real</td><td>同步后放弃时边跟随边抬升的距离，相对于动坐标系 Z 轴正方向的偏移量</td><td>—</td></tr><tr><td>ConvyGoto</td><td>label</td><td>跟随运动中无法继续跟随时，程序指针跳转的标签</td><td>—</td></tr><tr><td>[DO]</td><td>string</td><td>运动完成后触发的 IO 操作。支持：SetDO、SetAO、SetSimDO、SetSimAO、PulseOut、PulseSimOut、SetDO8421、SetSimDO8421、SetDIEdge、SetSimDIEdge</td><td>可选，默认 NULL（无操作）</td></tr></tbody></table>',9)])])}const m=d(r,[["render",n]]);export{_ as __pageData,m as default};
